'use client';

import { Fragment, useState } from 'react';

import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { type FactId, FIRST_FACT, HERO, PHRASES } from './data';
import { FactPicker } from './fact-picker';

/** The display rule of the home page: tight tracking on the display title and on nothing else. */
const STATEMENT =
  'text-[2.5rem] leading-[1.05] font-semibold tracking-[-0.03em] text-balance @2xl:text-6xl @5xl:text-7xl @5xl:leading-[1.02]';

/** The demonstration walks the facts in this order and ends where the hero began. */
const DEMO_ORDER: FactId[] = ['hourly', 'restore', 'laptops'];

const PICK_EVERY_MS = 2600;

function litOf(isLit: boolean) {
  if (isLit) {
    return '';
  }
  return undefined;
}

export default function Heroes04() {
  const [picked, setPicked] = useState<FactId>(FIRST_FACT);
  const { pressed, press } = usePress<FactId>();

  function startOver() {
    setPicked(FIRST_FACT);
  }

  const steps: AutoplayStep[] = DEMO_ORDER.flatMap((fact) => [
    { after: PICK_EVERY_MS, run: () => press(fact) },
    { after: PRESS_LEAD_MS, run: () => setPicked(fact) },
  ]);
  const { ref } = useAutoplay(steps, { loopAfter: 0, onReset: startOver });

  return (
    <section className='@container'>
      <div ref={ref} className='relative isolate'>
        <Wash className='h-[30rem]' />
        <div className='mx-auto flex max-w-6xl flex-col gap-12 px-4 py-16 @2xl:gap-14 @2xl:px-6 @2xl:py-24'>
          <div className='flex flex-col items-start gap-6'>
            <p className='text-primary-ink text-sm font-medium'>
              {HERO.eyebrow}
            </p>
            <h1 className={cn(STATEMENT, 'max-w-5xl')}>
              {PHRASES.map((phrase, index) => (
                <Fragment key={phrase.fact}>
                  {index > 0 && ' '}
                  <span
                    data-lit={litOf(phrase.fact === picked)}
                    className='data-lit:text-primary-ink transition-colors duration-300'
                  >
                    {phrase.text}
                  </span>
                </Fragment>
              ))}
            </h1>
            <p className='text-muted-foreground max-w-2xl text-base text-pretty @2xl:text-lg'>
              {HERO.lead}
            </p>
            <div className='flex flex-wrap gap-2 pt-1'>
              <Button size='lg' nativeButton={false} render={<a href='#' />}>
                {HERO.primaryAction}
                <ArrowRightIcon />
              </Button>
              <Button
                size='lg'
                variant='outline'
                nativeButton={false}
                render={<a href='#' />}
              >
                {HERO.secondaryAction}
              </Button>
            </div>
          </div>
          <FactPicker picked={picked} pressed={pressed} onPick={setPicked} />
        </div>
      </div>
    </section>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { type FactId, FACTS, HERO } from './data';

/** The picked fact sits on a card that travels from one fact to the next. */
const PICKED_CARD =
  'bg-card hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.06]';

const FACT_ITEM =
  'bg-foreground/[0.03] h-auto flex-col items-start justify-start gap-1 rounded-xl px-4 py-3.5 text-start whitespace-normal';

function isFactId(value: unknown): value is FactId {
  return FACTS.some((fact) => fact.id === value);
}

type FactPickerProps = {
  picked: FactId;
  /** The fact the demonstration is pressing, for the look of a press. */
  pressed: FactId | null;
  onPick: (fact: FactId) => void;
};

/** The facts row: three short facts, one picked at a time, each backing one part of the statement. */
export function FactPicker({ picked, pressed, onPick }: FactPickerProps) {
  const pickedValues = [picked];

  /** Pressing the picked fact again keeps it: a statement always has one fact behind it. */
  function change(values: unknown[]) {
    const [next] = values;
    if (isFactId(next)) {
      onPick(next);
    }
  }

  return (
    <ToggleGroup
      aria-label={HERO.factsLabel}
      value={pickedValues}
      onValueChange={change}
      travel
      indicatorClassName={PICKED_CARD}
      className='grid w-full items-stretch gap-2 @3xl:grid-cols-3'
    >
      {FACTS.map((fact) => (
        <ToggleGroupItem
          key={fact.id}
          value={fact.id}
          className={cn(FACT_ITEM, pressedQuietOf(pressed === fact.id))}
        >
          <span className='text-foreground text-sm font-medium'>
            {fact.title}
          </span>
          <span className='text-muted-foreground text-[13px] font-normal text-pretty'>
            {fact.detail}
          </span>
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

export type FactId = 'laptops' | 'hourly' | 'restore';

export type Phrase = {
  /** The fact that backs this part of the statement. */
  fact: FactId;
  text: string;
};

export type Fact = {
  id: FactId;
  title: string;
  detail: string;
};

export const HERO = {
  eyebrow: 'Laptop backups for teams of five to five hundred',
  lead: 'Keelbox copies what changed on each laptop to storage only your team can read, and puts any file back from the menu bar.',
  primaryAction: 'Start a 30-day trial',
  secondaryAction: 'See how a restore works',
  factsLabel: 'What the statement rests on',
};

export const PHRASES: Phrase[] = [
  { fact: 'laptops', text: 'Every laptop,' },
  { fact: 'hourly', text: 'every hour,' },
  { fact: 'restore', text: 'back in one click.' },
];

export const FACTS: Fact[] = [
  {
    id: 'laptops',
    title: 'Mac, Windows and Linux',
    detail:
      'One small agent per laptop, installed from a link you send to the team',
  },
  {
    id: 'hourly',
    title: 'Every hour, in the background',
    detail:
      'Only the parts of files that changed travel, so most backups end in under a minute',
  },
  {
    id: 'restore',
    title: 'Restore from the menu bar',
    detail:
      'Pick a file, a folder or a whole laptop, and any day of the last year to bring it back from',
  },
];

export const FIRST_FACT: FactId = 'laptops';
